    finish(m.id,'plan','모의 면접 보완·준비안만 복사','서비스를 실행하지 않았지만 모의 면접과 녹음·촬영·평가가 끝났고 점수로 합격·성격까지 확정했습니다.',['protocol','session','feedback','plan']);
